const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Paraná River delta geometry
  var delta = ee.Geometry.Polygon([
    [-59.5, -32.0],
    [-59.5, -33.0],
    [-58.5, -33.0],
    [-58.5, -32.0],
    [-59.5, -32.0]
  ]);

  // 2. Define time periods
  var start2019 = '2019-01-01';
  var end2019 = '2019-07-23';  // Exclusive, so use 23rd to include 22nd
  var start2020 = '2020-01-01';
  var end2020 = '2020-07-23';

  // 3. Use VIIRS Active Fires (375m daily) for fire detection
  var fires2019 = ee.ImageCollection('NOAA/VIIRS/001/VNP14A1')
    .filterDate(start2019, end2019)
    .filterBounds(delta)
    .select('FireMask');

  var fires2020 = ee.ImageCollection('NOAA/VIIRS/001/VNP14A1')
    .filterDate(start2020, end2020)
    .filterBounds(delta)
    .select('FireMask');

  // 4. Check collection sizes
  var count2019 = fires2019.size().getInfo();
  var count2020 = fires2020.size().getInfo();
  console.log(`2019 Images: ${count2019}, 2020 Images: ${count2020}`);

  // If either collection is empty, try MODIS as fallback
  if (count2019 === 0 || count2020 === 0) {
    console.log('Trying MODIS MCD14DL as fallback...');
    fires2019 = ee.ImageCollection('MODIS/006/MCD14DL')
      .filterDate(start2019, end2019)
      .filterBounds(delta)
      .select('confidence');
    fires2020 = ee.ImageCollection('MODIS/006/MCD14DL')
      .filterDate(start2020, end2020)
      .filterBounds(delta)
      .select('confidence');

    count2019 = fires2019.size().getInfo();
    count2020 = fires2020.size().getInfo();
    console.log(`MODIS 2019 Images: ${count2019}, 2020 Images: ${count2020}`);
  }

  // If still empty, output C1
  if (count2019 === 0 || count2020 === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  // 5. Process fire pixels: VIIRS FireMask values 7-9 = fire, MODIS confidence >=30 = fire
  var isVNP = fires2019.first().bandNames().getInfo().includes('FireMask');
  var fire2019, fire2020;

  if (isVNP) {
    // VIIRS: FireMask values 7,8,9 = fire
    fire2019 = fires2019.map(function(img) {
      var fire = img.gte(7).and(img.lte(9));
      return fire.rename('fire');
    }).sum();
    fire2020 = fires2020.map(function(img) {
      var fire = img.gte(7).and(img.lte(9));
      return fire.rename('fire');
    }).sum();
  } else {
    // MODIS: confidence >=30 = fire
    fire2019 = fires2019.map(function(img) {
      var fire = img.gte(30);
      return fire.rename('fire');
    }).sum();
    fire2020 = fires2020.map(function(img) {
      var fire = img.gte(30);
      return fire.rename('fire');
    }).sum();
  }

  // 6. Count fire pixels in each period
  var countFire2019 = fire2019.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: delta,
    scale: 1000,
    maxPixels: 1e9,
  }).get('fire').getInfo();

  var countFire2020 = fire2020.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: delta,
    scale: 1000,
    maxPixels: 1e9,
  }).get('fire').getInfo();

  // Check for valid pixel counts
  if (countFire2019 === null || countFire2020 === null) {
    console.log('<answer>C3</answer>');
    return;
  }

  // Round to integers
  countFire2019 = Math.round(countFire2019);
  countFire2020 = Math.round(countFire2020);

  console.log(`Fire hotspots 2019: ${countFire2019}`);
  console.log(`Fire hotspots 2020: ${countFire2020}`);

  // 7. Validate and output answer
  if (isNaN(countFire2019) || isNaN(countFire2020)) {
    console.log('<answer>C3</answer>');
  } else if (countFire2019 === 0 && countFire2020 === 0) {
    console.log('<answer>C2</answer>');
  } else if (countFire2020 > countFire2019) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
